/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isEmptyArrayLikeObject = require( '@stdlib/assert/is-empty-array-like-object' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var isScaleArray = require( '@stdlib/plot/vega/base/assert/is-scale-array' );
var copy = require( '@stdlib/array/base/copy' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:visualization:set:scales' );


// MAIN //

/**
* Sets the visualization scales.
*
* @private
* @param {ArrayLikeObject<Scale>} value - input value
* @throws {TypeError} must be an array of scale instances
* @returns {void}
*/
function set( value ) {
	if ( !isScaleArray( value ) && !isEmptyArrayLikeObject( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be an array of scale instances. Value: `%s`.', 'scales', value ) );
	}
	value = copy( value );
	if ( !hasEqualValues( value, this._scales ) ) {
		this._removeChangeListeners( this._scales );
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this._scales ), JSON.stringify( value ) );
		this._scales = value;
		this.emit( 'change' );
		this._addChangeListeners( this._scales );
	}
}


// EXPORTS //

module.exports = set;
